    162: { labels: { 'Kabuk': 'Скорлупа' },
      desc: 'Самоплодный поздноцветущий миндаль, выведенный во Франции. Не нужен опылитель и он уходит от весенних заморозков, поэтому подходит для односортовых садов; скорлупа твёрдая.',
      specs: { 'Çiçeklenme': 'Позднее', 'Hasat': 'Август–сентябрь', 'Kabuk': 'Твёрдая', 'Tozlayıcı': 'Самоплодный', 'Anavatan': 'Франция' } },
    163: { labels: { 'Kabuk': 'Скорлупа' },
      desc: 'Важнейший сорт грецкого ореха Калифорнии. Плодоносит и на боковых побегах, поэтому очень урожайный; цветёт очень поздно, ядро белое.',
      specs: { 'Ağaç': 'Плодоносит на боковых побегах, очень урожайный', 'Çiçeklenme': 'Очень позднее', 'Hasat': 'Конец сентября–октябрь', 'Ağırlık': 'В среднем 14 г', 'Kabuk': 'Очень светлая', 'İç': 'Белое', 'Tozlayıcı': 'Franquette', 'Anavatan': 'США (Калифорния)' } },
    164: { desc: 'Грецкий орех, выведенный во Франции от скрещивания Franquette × Lara. Поздно цветёт и уходит от весенних заморозков; опылитель — Fernette.',
      specs: { 'Çiçeklenme': 'Позднее', 'Hasat': 'Конец сентября–октябрь', 'Tozlayıcı': 'Fernette', 'Anavatan': 'Франция (Franquette × Lara)' } },
    165: { desc: 'Низкорослый урожайный грецкий орех, обильно плодоносящий и на боковых побегах (около 65%). Ядро в основном светлое; используется и как опылитель для поздноцветущих сортов.',
      specs: { 'Ağaç': 'Низкорослое, требует сильной обрезки', 'Öne çıkan': '65% плодоношения на боковых побегах', 'İç randımanı': '47%', 'İç': '85% светлых', 'Kullanım': 'Опылитель для поздноцветущих сортов', 'Anavatan': 'США (Калифорния)' } },
    166: { labels: { 'Kabuk': 'Скорлупа' },
      desc: 'Местный грецкий орех, связанный с Шебинкарахисаром (Гиресун). Густое раскидистое дерево даёт по 2–4 ореха в грозди; тонкая скорлупа, ядро легко извлекается, высокий выход ядра (63%).',
      specs: { 'Ağaç': 'Густая ветвистая раскидистая крона', 'Hasat': 'Конец сентября', 'Ağırlık': 'В среднем 12 г', 'Kabuk': 'Тонкая, ядро легко извлекается', 'İç randımanı': '63%', 'Tozlayıcı': 'Bilecik, KR-2, Yalova-1', 'Anavatan': 'Турция (Гиресун, Шебинкарахисар)' } },
    167: { labels: { 'Kabuk': 'Скорлупа' },
      desc: 'Местный грецкий орех, выращиваемый во внутренних районах. Прямостоячее раскидистое сильное дерево даёт по 2–3 ореха в грозди, около 30% — на боковых побегах; скорлупа тонкая.',
      specs: { 'Ağaç': 'Прямостоячее, раскидистое, сильное', 'Öne çıkan': '30% плодов на боковых побегах', 'Ağırlık': 'В среднем 13 г', 'Kabuk': 'Тонкая, ядро легко извлекается', 'İç randımanı': '53%', 'Anavatan': 'Турция' } },
    168: { labels: { 'Meyve şekli': 'Форма ореха' },
      desc: 'Классический французский сорт грецкого ореха. Поздно распускается и цветёт, уходя от весенних заморозков; даёт удлинённые качественные орехи и опыляет такие сорта, как Chandler.',
      specs: { 'Çiçeklenme': 'Позднее (поздно распускается)', 'Hasat': 'Октябрь', 'Meyve şekli': 'Удлинённая', 'Kullanım': 'Опылитель для Chandler и Fernor', 'Anavatan': 'Франция' } },
    169: { desc: 'Поздноцветущий грецкий орех, выведенный во Франции от скрещивания Franquette × Lara. Опылитель сорта Fernor.',
      specs: { 'Çiçeklenme': 'Позднее', 'Hasat': 'Конец сентября–октябрь', 'Kullanım': 'Опылитель для Fernor', 'Anavatan': 'Франция (Franquette × Lara)' } },
    170: { labels: { 'Kabuk': 'Кожица' },
      desc: 'Вяжущая хурма из региона Валенсия (Испания). Крупные плоды снимают твёрдыми; после удаления терпкости их можно есть хрустящими и сладкими, как яблоко, или есть после размягчения.',
      specs: { 'Hasat': 'Октябрь–декабрь', 'İrilik': 'Крупный', 'Kabuk': 'Оранжево-красная', 'Tat': 'Вяжущий; после удаления терпкости хрустящий и сладкий', 'Anavatan': 'Испания (Валенсия)' } },
    171: { labels: { 'Kabuk': 'Кожица' },
      desc: 'Крупная невяжущая хурма японского происхождения («гигантская Фуйю»). Самоплодная; плоды сладкие даже твёрдыми, осенью листва очень красочная.',
      specs: { 'Hasat': 'Октябрь–ноябрь', 'İrilik': 'Очень крупный', 'Kabuk': 'Оранжевая с красноватым оттенком', 'Tat': 'Невяжущий, сладкий', 'Tozlayıcı': 'Самоплодная', 'Anavatan': 'Япония' } },
    172: { title: 'Кумкват',
      desc: 'Низкорослый цитрус с маленькими овальными оранжевыми плодами, которые едят вместе с кожурой. Кожура сладкая, мякоть кисловатая. Остаётся небольшим, поэтому его выращивают и в горшках на балконах и террасах; один из самых морозостойких цитрусов.',
      specs: { 'Meyve': 'Маленький, овальный, оранжевый', 'Tat': 'Сладкая кожура, кисловатая мякоть; едят с кожурой', 'Hasat': 'Зимние месяцы', 'Ağaç': 'Низкорослое, подходит для горшков', 'Dayanıklılık': 'Один из самых морозостойких цитрусов', 'Kullanım': 'В свежем виде, для варенья и цукатов; также декоративный', 'Anavatan': 'Китай' } },
    /* ---------- Sağ Tarım'dan eklenen çeşitler ---------- */
    173: { title: "Апельсин Ризе",
      desc: "Апельсин анатолийского происхождения: дерево быстро растёт и рано вступает в плодоношение. Плоды средней величины, сочные и очень вкусные.",
      specs: { "Hasat": "С января", "Meyve": "Средние, сочные и вкусные", "Ağaç": "Быстрорастущее, рано плодоносит", "Tozlayıcı": "Самоплодный (опылитель повышает урожай)", "Dayanıklılık": "Выносливое дерево", "Anavatan": "Анатолия" } },
